import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useLanguage } from '../../context/LanguageContext';
import { useTheme } from '../../context/ThemeContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PhoneInput from '../../components/common/PhoneInput/PhoneInput';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import styles from './ProfilePage.module.css';

const ProfilePage = () => {
    const { user, updateProfile, changePassword, deleteAccount, logout } = useAuth();
    const { t, changeLanguage } = useLanguage();
    const { theme, changeTheme } = useTheme();

    // ... остальные функции (getLevelFromNumber, getLevelNumber, generateRandomPassword и т.д.)

    const handleSaveProfile = async (e) => {
        e.preventDefault();
        if (!validateProfileForm()) return;
        setLoading(true);
        try {
            const profileToSend = {
                ...profile,
                gameLevel: getLevelNumber(profile.gameLevel)
            };
            await updateProfile(profileToSend);

            // Применяем язык и тему глобально
            changeLanguage(profile.language);
            changeTheme(profile.theme);

            setMessage({ text: t('profileUpdated'), type: 'success' });
            setTimeout(() => setMessage({ text: '', type: '' }), 3000);
        } catch (err) {
            if (err.message?.toLowerCase().includes('email')) {
                setProfileErrors({ ...profileErrors, email: 'Пользователь с таким email уже существует' });
                setMessage({ text: '', type: '' });
            } else {
                setMessage({ text: err.message || t('updateError'), type: 'error' });
            }
        } finally {
            setLoading(false);
        }
    };

    const handleLanguageChange = (lang) => {
        setProfile({ ...profile, language: lang });
        changeLanguage(lang);
        if (message.text) setMessage({ text: '', type: '' });
    };

    const handleThemeChange = (newTheme) => {
        setProfile({ ...profile, theme: newTheme });
        changeTheme(newTheme);
        if (message.text) setMessage({ text: '', type: '' });
    };

    // ... остальной код с использованием t() для текстов

    return (
        <div className={styles.profilePage}>
            <div className={styles.container}>
                <div className={styles.profileCard}>
                    <div className={styles.header}>
                        <h1 className={styles.title}>{t('personalAccount')}</h1>
                    </div>
                    {/* ... остальной JSX с использованием t() */}
                </div>
            </div>
        </div>
    );
};

export default ProfilePage;
